<?php require 'config/database.php'; require 'includes/auth.php'; if(logged()){header('Location:index.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $st=$pdo->prepare("SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username=? AND u.status='aktif' LIMIT 1");$st->execute([trim($_POST['username']??'')]);$u=$st->fetch();if($u && password_verify($_POST['password']??'',$u['password'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'username'=>$u['username'],'role'=>$u['role_name']];header('Location:index.php');exit;} $err='Username atau password salah.';} ?>
